CREATE TABLE IF NOT EXISTS lab_section (id CHAR(36) PRIMARY KEY, code VARCHAR(20) NOT NULL, name VARCHAR(80) NOT NULL, sort_order SMALLINT NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY lab_section_code_unique (code), UNIQUE KEY lab_section_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_store (id CHAR(36) PRIMARY KEY, kind VARCHAR(8) NOT NULL, section_id CHAR(36) NULL, created_at DATETIME NOT NULL, UNIQUE KEY lab_store_section_unique (section_id), CONSTRAINT lab_store_section_fk FOREIGN KEY (section_id) REFERENCES lab_section(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_item (id CHAR(36) PRIMARY KEY, code VARCHAR(30) NOT NULL, name VARCHAR(200) NOT NULL, receive_unit VARCHAR(30) NOT NULL, use_unit VARCHAR(30) NOT NULL, units_per_receive INT NOT NULL, expiry_warn_days SMALLINT NOT NULL DEFAULT 90, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY lab_item_code_unique (code), CONSTRAINT lab_item_factor_positive CHECK (units_per_receive >= 1)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_item_reorder (item_id CHAR(36) NOT NULL, store_id CHAR(36) NOT NULL, reorder_point INT NOT NULL, PRIMARY KEY (item_id, store_id), CONSTRAINT lab_item_reorder_item_fk FOREIGN KEY (item_id) REFERENCES lab_item(id), CONSTRAINT lab_item_reorder_store_fk FOREIGN KEY (store_id) REFERENCES lab_store(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_vendor (id CHAR(36) PRIMARY KEY, name VARCHAR(200) NOT NULL, phone VARCHAR(40) NOT NULL DEFAULT '', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY lab_vendor_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_usage_type (id CHAR(36) PRIMARY KEY, name VARCHAR(60) NOT NULL, sort_order SMALLINT NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY lab_usage_type_name_unique (name)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_member (person_id CHAR(36) PRIMARY KEY, role VARCHAR(8) NOT NULL, created_at DATETIME NOT NULL, created_by CHAR(36) NOT NULL, CONSTRAINT lab_member_person_fk FOREIGN KEY (person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_member_section (person_id CHAR(36) NOT NULL, section_id CHAR(36) NOT NULL, PRIMARY KEY (person_id, section_id), CONSTRAINT lab_member_section_member_fk FOREIGN KEY (person_id) REFERENCES lab_member(person_id) ON DELETE CASCADE, CONSTRAINT lab_member_section_section_fk FOREIGN KEY (section_id) REFERENCES lab_section(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_setting (setting_key VARCHAR(64) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL, updated_at DATETIME NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_doc_counter (prefix VARCHAR(8) NOT NULL, fiscal_year SMALLINT NOT NULL, last_no INT NOT NULL, PRIMARY KEY (prefix, fiscal_year)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_receipt (id CHAR(36) PRIMARY KEY, doc_no VARCHAR(20) NOT NULL, received_on DATE NOT NULL, vendor_id CHAR(36) NOT NULL, invoice_no VARCHAR(60) NOT NULL DEFAULT '', status VARCHAR(8) NOT NULL, void_reason VARCHAR(1000) NULL, created_by CHAR(36) NOT NULL, created_at DATETIME NOT NULL, voided_by CHAR(36) NULL, voided_at DATETIME NULL, UNIQUE KEY lab_receipt_doc_unique (doc_no), KEY lab_receipt_received (received_on), CONSTRAINT lab_receipt_vendor_fk FOREIGN KEY (vendor_id) REFERENCES lab_vendor(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_receipt_line (id CHAR(36) PRIMARY KEY, receipt_id CHAR(36) NOT NULL, line_no SMALLINT NOT NULL, item_id CHAR(36) NOT NULL, lot_no VARCHAR(60) NOT NULL, expiry_date DATE NULL, quantity_receive INT NOT NULL, price_per_receive DECIMAL(12,2) NOT NULL, lot_id CHAR(36) NOT NULL, KEY lab_receipt_line_receipt (receipt_id, line_no), CONSTRAINT lab_receipt_line_receipt_fk FOREIGN KEY (receipt_id) REFERENCES lab_receipt(id), CONSTRAINT lab_receipt_line_item_fk FOREIGN KEY (item_id) REFERENCES lab_item(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_lot (id CHAR(36) PRIMARY KEY, item_id CHAR(36) NOT NULL, lot_no VARCHAR(60) NOT NULL, expiry_date DATE NULL, expiry_key DATE AS (IFNULL(expiry_date, '9999-12-31')) PERSISTENT, unit_cost DECIMAL(14,4) NOT NULL, source VARCHAR(8) NOT NULL, receipt_line_id CHAR(36) NULL, created_at DATETIME(6) NOT NULL, UNIQUE KEY lab_lot_identity_unique (item_id, lot_no, expiry_key, unit_cost), CONSTRAINT lab_lot_item_fk FOREIGN KEY (item_id) REFERENCES lab_item(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_lot_balance (lot_id CHAR(36) NOT NULL, store_id CHAR(36) NOT NULL, quantity INT NOT NULL, PRIMARY KEY (lot_id, store_id), KEY lab_lot_balance_store (store_id), CONSTRAINT lab_lot_balance_nonnegative CHECK (quantity >= 0), CONSTRAINT lab_lot_balance_lot_fk FOREIGN KEY (lot_id) REFERENCES lab_lot(id), CONSTRAINT lab_lot_balance_store_fk FOREIGN KEY (store_id) REFERENCES lab_store(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_movement (id CHAR(36) PRIMARY KEY, lot_id CHAR(36) NOT NULL, store_id CHAR(36) NOT NULL, quantity INT NOT NULL, kind VARCHAR(16) NOT NULL, entry_date DATE NOT NULL, usage_type_id CHAR(36) NULL, ref_type VARCHAR(16) NOT NULL, ref_id CHAR(36) NOT NULL, note VARCHAR(500) NOT NULL DEFAULT '', created_by CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, KEY lab_movement_store_date (store_id, entry_date), KEY lab_movement_lot (lot_id), KEY lab_movement_ref (ref_type, ref_id), CONSTRAINT lab_movement_lot_fk FOREIGN KEY (lot_id) REFERENCES lab_lot(id), CONSTRAINT lab_movement_store_fk FOREIGN KEY (store_id) REFERENCES lab_store(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_opening_line (id CHAR(36) PRIMARY KEY, row_no INT NOT NULL, store_id CHAR(36) NOT NULL, item_id CHAR(36) NOT NULL, lot_no VARCHAR(60) NOT NULL, expiry_date DATE NULL, quantity INT NOT NULL, unit_cost DECIMAL(14,4) NOT NULL, CONSTRAINT lab_opening_line_store_fk FOREIGN KEY (store_id) REFERENCES lab_store(id), CONSTRAINT lab_opening_line_item_fk FOREIGN KEY (item_id) REFERENCES lab_item(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_requisition (id CHAR(36) PRIMARY KEY, doc_no VARCHAR(20) NOT NULL, section_id CHAR(36) NOT NULL, status VARCHAR(10) NOT NULL, note VARCHAR(500) NOT NULL DEFAULT '', requested_by CHAR(36) NOT NULL, requested_at DATETIME NOT NULL, decided_by CHAR(36) NULL, decided_at DATETIME NULL, decision_reason VARCHAR(1000) NULL, issued_by CHAR(36) NULL, issued_at DATETIME NULL, issue_note VARCHAR(500) NULL, UNIQUE KEY lab_requisition_doc_unique (doc_no), KEY lab_requisition_status (status, requested_at), CONSTRAINT lab_requisition_section_fk FOREIGN KEY (section_id) REFERENCES lab_section(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_requisition_line (id CHAR(36) PRIMARY KEY, requisition_id CHAR(36) NOT NULL, line_no SMALLINT NOT NULL, item_id CHAR(36) NOT NULL, quantity_requested INT NOT NULL, quantity_issued INT NULL, KEY lab_requisition_line_req (requisition_id, line_no), CONSTRAINT lab_requisition_line_req_fk FOREIGN KEY (requisition_id) REFERENCES lab_requisition(id), CONSTRAINT lab_requisition_line_item_fk FOREIGN KEY (item_id) REFERENCES lab_item(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lab_usage (id CHAR(36) PRIMARY KEY, store_id CHAR(36) NOT NULL, item_id CHAR(36) NOT NULL, quantity INT NOT NULL, usage_type_id CHAR(36) NOT NULL, entry_date DATE NOT NULL, note VARCHAR(500) NOT NULL DEFAULT '', status VARCHAR(8) NOT NULL, reverse_reason VARCHAR(1000) NULL, created_by CHAR(36) NOT NULL, created_at DATETIME NOT NULL, reversed_by CHAR(36) NULL, reversed_at DATETIME NULL, KEY lab_usage_store_date (store_id, entry_date), CONSTRAINT lab_usage_store_fk FOREIGN KEY (store_id) REFERENCES lab_store(id), CONSTRAINT lab_usage_item_fk FOREIGN KEY (item_id) REFERENCES lab_item(id), CONSTRAINT lab_usage_type_fk FOREIGN KEY (usage_type_id) REFERENCES lab_usage_type(id)) DEFAULT CHARSET=utf8mb4;
